# Faça um programa que leia um número inteiro qualquer e mostre na tela a sua tabuada.
numero = float(input('Digite um número que deseje saber sua tabuada: '))

print(f'\n{numero:.2f} x 1 = {(numero * 1):.2f}\n{numero:.2f} x 2 = {(numero * 2):.2f}\n{numero:.2f} x 3 = {(numero * 3):.2f}\n{numero:.2f} x 4 = {(numero * 4):.2f}\n{numero:.2f} x 5 = {(numero * 5):.2f}\n{numero:.2f} x 6 = {(numero * 6):.2f}\n{numero:.2f} x 7 = {(numero * 7):.2f}\n{numero:.2f} x 8 = {(numero * 8):.2f}\n{numero:.2f} x 9 = {(numero * 9):.2f}\n')